/**
 * Where the points came from, round by round, read from RoboNation's published score sheets
 * (mongla_ws docs/data/robosub.json, generated by tools/site/robosub_record.py, never typed in).
 */
import data from "../data/mongla.json";
import { C, s, svg, h, readout, choice } from "./kit";

type Task = { task: string; points: number };
type Round = { score: number; tasks: Task[]; rank: number };
type Year = { teams: number; rounds: Record<string, Round>; wildcard: number; overall: { rank: number; score: number } };

const GROUPS: [RegExp, string, string][] = [
  [/^Gate/i, "gate", C.medium],
  [/Debris|slalom/i, "slalom", C.measured],
  [/Restore|Surface|octagon/i, "surface", C.me],
  [/Return/i, "return home", C.estimate],
  [/Weight/i, "weight bonus", C.dim],
];
const groupOf = (t: string) => GROUPS.find(([re]) => re.test(t)) ?? [/./, "other tasks", C.chalk] as const;

export function mount(root: HTMLElement) {
  const years = data.robosub.years as unknown as Record<string, Year>;
  const keys = Object.keys(years).sort();
  let yk = keys[keys.length - 1];
  const W = 860, L = 140, R = 820;
  const host = h("div", {}, root);
  const say = readout(root);
  const draw = () => {
    host.replaceChildren();
    const y = years[yk];
    const rounds = Object.entries(y.rounds);
    const max = Math.max(y.wildcard, ...rounds.map(([, r]) => r.score)) * 1.08;
    const x = (v: number) => L + (Math.max(0, v) / max) * (R - L);
    const el = svg(host, W, 60 + rounds.length * 62, `RoboSub ${yk}: points per round by task group, against the finals wild-card line`);
    s("line", { x1: x(y.wildcard), x2: x(y.wildcard), y1: 14, y2: 30 + rounds.length * 62, stroke: C.failure, "stroke-width": 2, "stroke-dasharray": "6 4" }, el);
    s("text", { x: x(y.wildcard) + 6, y: 22, class: "x-lbl", fill: C.failure }, el).textContent = `finals wild card ${y.wildcard.toLocaleString("en-US")}`;
    rounds.forEach(([name, r], i) => {
      const yy = 40 + i * 62;
      s("text", { x: L - 10, y: yy + 18, "text-anchor": "end", class: "x-lbl" }, el).textContent = name;
      s("text", { x: L - 10, y: yy + 34, "text-anchor": "end", class: "x-tick" }, el).textContent = `rank #${r.rank}`;
      let acc = 0;
      const sums = new Map<string, { pts: number; col: string; tasks: string[] }>();
      for (const t of r.tasks) { const [, g, col] = groupOf(t.task); const e = sums.get(g) ?? { pts: 0, col, tasks: [] }; e.pts += t.points; e.tasks.push(`${t.task} ${t.points}`); sums.set(g, e); }
      for (const [g, e] of sums) {
        if (e.pts <= 0) continue;
        const seg = s("rect", { x: x(acc), y: yy, width: Math.max(1, x(acc + e.pts) - x(acc) - 1.5), height: 30, rx: 2, fill: e.col, opacity: 0.85, tabindex: 0, role: "img", "aria-label": `${name}, ${g}: ${e.pts} points` }, el);
        const show = () => say(`<b>${yk} · ${name} · ${g}: ${e.pts.toLocaleString("en-US")} points</b>. ${e.tasks.join(" · ")}`);
        seg.addEventListener("pointerenter", show); seg.addEventListener("focus", show);
        acc += e.pts;
      }
      s("text", { x: x(r.score) + 8, y: yy + 20, class: "x-lbl", fill: C.chalk }, el).textContent = r.score.toLocaleString("en-US");
    });
    const best = Math.max(...rounds.map(([, r]) => r.score));
    say(`RoboSub ${yk}: <b>${y.overall.rank}th of ${y.teams}</b>, best round <b>${best.toLocaleString("en-US")}</b>, ${best >= y.wildcard ? `<b class="k-estimate">over</b> the wild-card line, on a third-chance run, and still not one of the seven finalists.` : `<b class="k-failure">${(y.wildcard - best).toLocaleString("en-US")} short of</b> the wild-card line.`} Hover a block for its tasks.`);
  };
  choice(root, "Year", keys.map((k) => ({ label: `RoboSub ${k}`, on: () => { yk = k; draw(); } })), keys.length - 1);
  const legend = h("p", { class: "bench-note" }, root);
  legend.innerHTML = GROUPS.map(([, g, c]) => `<span style="color:${c}">■</span> ${g}`).join(" &nbsp; ") + ". Team results: the vehicles and missions were the team's; I led vision in 2025 and engineering in 2026.";
  draw();
}
